<div class="page-title">P&amp;L Goals</div><p class="page-subtitle">Set target net P&amp;L for each account across daily, weekly, monthly and yearly periods.</p>
<div class="card form-card"><div class="section-heading"><div><h2>Set goals</h2><div class="sub">Goals are stored per account and can be changed at any time.</div></div></div><form method="post" action="/goals"><?=csrf_field()?><div class="grid"><p><label>Account</label><select name="account_id" required><option value="">Select account...</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['name'].' ('.$a['currency'].')')?></option><?php endforeach;?></select></p><p><label>Daily P&amp;L goal</label><input type="number" step="0.01" min="0" name="daily_goal" value="0" required></p><p><label>Weekly P&amp;L goal</label><input type="number" step="0.01" min="0" name="weekly_goal" value="0" required></p><p><label>Monthly P&amp;L goal</label><input type="number" step="0.01" min="0" name="monthly_goal" value="0" required></p><p><label>Yearly P&amp;L goal</label><input type="number" step="0.01" min="0" name="yearly_goal" value="0" required></p></div><div class="actions"><button>Save goals</button></div></form></div>
<div class="card table-wrap"><div class="section-heading"><div><h2>Current goals</h2><div class="sub">One goal profile per account.</div></div></div><table><thead><tr><th>Account</th><th>Daily</th><th>Weekly</th><th>Monthly</th><th>Yearly</th></tr></thead><tbody><?php foreach($goals as $g):?><tr><td><?=e($g['account_name'])?> <span class="muted"><?=e($g['currency'])?></span></td><td><?=number_format((float)$g['daily_goal'],2)?></td><td><?=number_format((float)$g['weekly_goal'],2)?></td><td><?=number_format((float)$g['monthly_goal'],2)?></td><td><?=number_format((float)$g['yearly_goal'],2)?></td></tr><?php endforeach;?><?php if(!$goals):?><tr><td colspan="5" class="muted">No P&amp;L goals configured yet.</td></tr><?php endif;?></tbody></table></div>
